      SUBROUTINE DECARB(INAME)      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM14A.CIN'      INCLUDE 'KELEM.CIN'      INCLUDE 'KNAME.CIN'      INCLUDE 'LNAME.CIN'      INCLUDE 'PARDAT.CIN'      INCLUDE 'PARVAL.CIN'C      CALL FNMTX(KNAME,LNAME,INAME)      IPTYP(7) = 1      PDATA(7) = FLOAT(J1)      IF (IPARM .GE. 8) THEN        IPTYP(8) = 1        PDATA(8) = 0.0      ENDIF      IF (IPARM .GE. 30) THEN        IPTYP(30) = 1        PDATA(30) = 0.0      ENDIF      RETURN      END